  for chunk in case_answer.get(\"_chunks\", [])[:3]:\n                evidence.append({\n                    \"source\": chunk.get(\"source\"),\n                    \"score\": chunk.get(\"_case_score\", 0.0)\n                })\n            latency_ms = int((datetime.now(timezone.utc) - started).total_seconds() * 1000)\n            langfuse = _send_langfuse(\n                \"kb_answer\", query, answer, evidence, \"General\",\n                [\"case_study\"], \"overview\", False, latency_ms, context, params,\n                channel_type=detected_channel,\n                original_query=original_query,\n                correlation_id=correlation_id,\n                parent_trace_id=parent_trace_id,\n            policy_meta={},\n        )\n            return {\n                \"ok\": True,\n                \"query\": _redact_secrets_in_query_echo(query),\n                \"answer\": answer,\n                \"citations\": [],\n                \"langfuse\": langfuse,\n            }\n\n    scored = []\n    for c in product_chunks:\n        s = _score_chunk(query, c, entities, explicit_module)\n        if s >= MIN_CHUNK_SCORE:\n            row = dict(c)\n            row[\"score\"] = s\n            scored.append(row)\n    scored.sort(key=lambda x: x.get(\"score\", 0.0), reverse=True)\n\n    # Filter out retrieval magnets: chunks where the entire score comes from\n    # generic path/heading tokens with zero real content overlap. These docs\n    # legitimately exist (CTX, Instagram, Account docs) but over-match off-topic\n    # queries that happen to mention the same generic words.\n    scored = _filter_magnet_matches(query, scored)\n\n    evidence = _select_evidence(query, scored, intent, explicit_module)\n    answer, answer_mode = _route_answer_composer(query, intent, entities, evidence, explicit_module, params, all_chunks=chunks)\n    answer, policy_meta = _apply_answer_policy(answer, query, params)\n    policy_meta = dict(policy_meta or {})\n    policy_meta[\"answer